# Re-examine the test input for any patterns I might have missed
test_input = [
    [9, 9, 9, 2, 9, 9, 5, 9, 9, 9, 9],
    [9, 9, 9, 9, 6, 9, 9, 9, 9, 9, 9],
    [9, 5, 9, 9, 1, 9, 9, 5, 9, 9, 9],
    [9, 9, 9, 4, 9, 9, 2, 9, 3, 7, 9],
    [9, 4, 8, 8, 9, 9, 9, 2, 9, 9, 9],
    [9, 9, 5, 9, 8, 9, 0, 9, 9, 9, 1],
    [9, 9, 7, 9, 8, 6, 0, 9, 9, 9, 9],
    [9, 9, 6, 9, 9, 9, 7, 9, 9, 9, 9],
    [0, 9, 9, 9, 7, 9, 9, 9, 9, 9, 9],
    [9, 9, 3, 9, 9, 1, 1, 1, 1, 1, 9],
    [3, 0, 9, 9, 6, 1, 1, 1, 1, 1, 9],
    [9, 9, 7, 9, 9, 1, 1, 1, 1, 1, 9],
    [9, 9, 9, 9, 9, 1, 1, 1, 1, 1, 9],
    [6, 9, 2, 9, 9, 1, 1, 1, 1, 1, 5],
    [9, 9, 9, 9, 3, 1, 1, 1, 1, 1, 9],
    [9, 9, 9, 3, 9, 5, 8, 1, 9, 9, 9]
]

# Check if there could be any other interpretation
# Maybe the task is different - let me print out what I see

print("Looking for horizontal lines of same color:")
for c in range(11):
    cols = []
    for r in range(16):
        cols.append(test_input[r][c])

    # Find longest run of same color
    if len(cols) > 0:
        max_run = 1
        cur_run = 1
        for i in range(1, len(cols)):
            if cols[i] == cols[i-1]:
                cur_run += 1
                if cur_run > max_run:
                    max_run = cur_run
            else:
                cur_run = 1
        if max_run >= 5:
            # Find where it starts
            start = 0
            while start < len(cols) - max_run + 1:
                match = True
                for j in range(max_run):
                    if cols[start+j] != cols[start]:
                        match = False
                        break
                if match:
                    start_idx = cols.index(cols[start], start)
                    end_idx = start_idx + max_run
                    print(f"Column {c}: run of {cols[start]} length {max_run} at rows {start_idx}-{end_idx-1}")
                    break
                start += 1

print("\n\nLooking for vertical lines of same color:")
for r in range(16):
    rows = []
    for c in range(11):
        rows.append(test_input[r][c])

    if len(rows) > 0:
        max_run = 1
        cur_run = 1
        for i in range(1, len(rows)):
            if rows[i] == rows[i-1]:
                cur_run += 1
                if cur_run > max_run:
                    max_run = cur_run
            else:
                cur_run = 1
        if max_run >= 5:
            start = 0
            while start < len(rows) - max_run + 1:
                match = True
                for j in range(max_run):
                    if rows[start+j] != rows[start]:
                        match = False
                        break
                if match:
                    start_col = rows.index(rows[start], start)
                    end_col = start_col + max_run
                    print(f"Row {r}: run of {rows[start]} length {max_run} at cols {start_col}-{end_col-1}")
                    break
                start += 1

